import { PROTOCOL_VERSION, agent as createAgentApp, methods } from "../acp.js";

import type {
  Agent,
  AgentApp,
  AgentSideConnection,
  AuthenticateRequest,
  AuthenticateResponse,
  CancelNotification,
  InitializeRequest,
  InitializeResponse,
  NewSessionRequest,
  NewSessionResponse,
  PromptRequest,
  PromptResponse,
} from "../acp.js";

export interface TestAgentOptions {
  readonly chunkCount?: number;
  readonly chunkDelayMs?: number;
  readonly enablePermission?: boolean;
}

export interface TestAgentAppOptions extends TestAgentOptions {
  readonly initialize?: (
    params: InitializeRequest,
  ) => Promise<InitializeResponse> | InitializeResponse;
  readonly onInitialize?: () => void;
  readonly newSession?: (
    params: NewSessionRequest,
  ) => Promise<NewSessionResponse> | NewSessionResponse;
}

export class TestAgent implements Agent {
  private readonly connection: AgentSideConnection;
  private readonly chunkCount: number;
  private readonly chunkDelayMs: number;
  private readonly enablePermission: boolean;

  constructor(connection: AgentSideConnection, options: TestAgentOptions = {}) {
    this.connection = connection;
    this.chunkCount = options.chunkCount ?? 1;
    this.chunkDelayMs = options.chunkDelayMs ?? 0;
    this.enablePermission = options.enablePermission ?? false;
  }

  initialize(_params: InitializeRequest): Promise<InitializeResponse> {
    return Promise.resolve({
      protocolVersion: PROTOCOL_VERSION,
      agentCapabilities: {
        loadSession: false,
      },
    });
  }

  newSession(_params: NewSessionRequest): Promise<NewSessionResponse> {
    return Promise.resolve({ sessionId: globalThis.crypto.randomUUID() });
  }

  authenticate(
    _params: AuthenticateRequest,
  ): Promise<AuthenticateResponse | void> {
    return Promise.resolve();
  }

  async prompt(params: PromptRequest): Promise<PromptResponse> {
    for (const index of Array.from(
      { length: this.chunkCount },
      (_, item) => item,
    )) {
      if (this.chunkDelayMs > 0) {
        await delay(this.chunkDelayMs);
      }

      await this.connection.sessionUpdate({
        sessionId: params.sessionId,
        update: {
          sessionUpdate: "agent_message_chunk",
          content: {
            type: "text",
            text: `chunk-${index + 1}`,
          },
        },
      });
    }

    if (this.enablePermission) {
      const permission = await this.connection.requestPermission({
        sessionId: params.sessionId,
        toolCall: {
          toolCallId: "permission-tool",
          title: "Permission tool",
        },
        options: [
          {
            kind: "allow_once",
            name: "Allow once",
            optionId: "allow",
          },
          {
            kind: "reject_once",
            name: "Reject once",
            optionId: "reject",
          },
        ],
      });

      await this.connection.sessionUpdate({
        sessionId: params.sessionId,
        update: {
          sessionUpdate: "agent_message_chunk",
          content: {
            type: "text",
            text:
              permission.outcome.outcome === "selected"
                ? `permission-selected-${permission.outcome.optionId}`
                : "permission-cancelled",
          },
        },
      });
    }

    return { stopReason: "end_turn" };
  }

  cancel(_params: CancelNotification): Promise<void> {
    return Promise.resolve();
  }
}

export function createTestAgentApp(
  options: TestAgentAppOptions = {},
): AgentApp {
  return createAgentApp({ name: "test-agent" })
    .onRequest(methods.agent.initialize, async (c) => {
      options.onInitialize?.();

      if (options.initialize) {
        return await options.initialize(c.params);
      }

      return {
        protocolVersion: PROTOCOL_VERSION,
        agentCapabilities: {
          loadSession: false,
        },
      };
    })
    .onRequest(methods.agent.session.new, async (c) => {
      if (options.newSession) {
        return await options.newSession(c.params);
      }

      return { sessionId: globalThis.crypto.randomUUID() };
    })
    .onRequest(methods.agent.authenticate, () => ({}))
    .onRequest(methods.agent.session.prompt, async (c) => {
      const chunkCount = options.chunkCount ?? 1;
      const chunkDelayMs = options.chunkDelayMs ?? 0;

      for (const index of Array.from(
        { length: chunkCount },
        (_, item) => item,
      )) {
        if (chunkDelayMs > 0) {
          await delay(chunkDelayMs);
        }

        await c.client.notify(methods.client.session.update, {
          sessionId: c.params.sessionId,
          update: {
            sessionUpdate: "agent_message_chunk",
            content: {
              type: "text",
              text: `chunk-${index + 1}`,
            },
          },
        });
      }

      if (options.enablePermission) {
        const permission = await c.client.request(
          methods.client.session.requestPermission,
          {
            sessionId: c.params.sessionId,
            toolCall: {
              toolCallId: "permission-tool",
              title: "Permission tool",
            },
            options: [
              {
                kind: "allow_once",
                name: "Allow once",
                optionId: "allow",
              },
              {
                kind: "reject_once",
                name: "Reject once",
                optionId: "reject",
              },
            ],
          },
        );

        await c.client.notify(methods.client.session.update, {
          sessionId: c.params.sessionId,
          update: {
            sessionUpdate: "agent_message_chunk",
            content: {
              type: "text",
              text:
                permission.outcome.outcome === "selected"
                  ? `permission-selected-${permission.outcome.optionId}`
                  : "permission-cancelled",
            },
          },
        });
      }

      return { stopReason: "end_turn" };
    })
    .onNotification(methods.agent.session.cancel, () => {});
}

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
}

import { describe, expect, it } from "vitest";
import {
  EVENT_STREAM_MIME_TYPE,
  HEADER_CONNECTION_ID,
  HEADER_SESSION_ID,
  JSON_MIME_TYPE,
} from "./protocol.js";
import { parseSseStream } from "./sse.js";
import { createTestAgentApp } from "./test-support/test-agent.js";
import { startTestServer } from "./test-support/test-http-server.js";

import type { AnyMessage } from "./jsonrpc.js";

const initializeRequest = {
  jsonrpc: "2.0",
  id: 1,
  method: "initialize",
  params: {
    protocolVersion: 1,
    clientCapabilities: {},
  },
};

const sessionNewRequest = {
  jsonrpc: "2.0",
  id: 2,
  method: "session/new",
  params: {
    cwd: "/tmp",
    mcpServers: [],
  },
};

function createPromptRequest(id: number, sessionId: string) {
  return {
    jsonrpc: "2.0",
    id,
    method: "session/prompt",
    params: {
      sessionId,
      prompt: [{ type: "text", text: "Hello" }],
    },
  };
}

describe("AcpServer permission requests over HTTP", () => {
  it("rejects session-scoped client responses without a session header", async () => {
    const server = await startTestServer(() =>
      createTestAgentApp({ enablePermission: true }),
    );

    try {
      const connectionId = await initialize(server.url);
      const sessionId = await createSession(server.url, connectionId);
      const sessionSse = await openSessionSse(
        server.url,
        connectionId,
        sessionId,
      );
      const sessionEvents = createSseMessageIterator(sessionSse);

      expect(
        await postJson(server.url, createPromptRequest(3, sessionId), {
          [HEADER_CONNECTION_ID]: connectionId,
          [HEADER_SESSION_ID]: sessionId,
        }),
      ).toMatchObject({ status: 202 });

      await readNextSseMessage(sessionEvents);
      const permissionRequest = await readNextSseMessage(sessionEvents);

      const permissionResponse = {
        jsonrpc: "2.0",
        id: readMessageId(permissionRequest),
        result: {
          outcome: {
            outcome: "selected",
            optionId: "allow",
          },
        },
      };

      expect(
        await postJson(server.url, permissionResponse, {
          [HEADER_CONNECTION_ID]: connectionId,
        }),
      ).toMatchObject({ status: 400 });
      expect(
        await postJson(server.url, permissionResponse, {
          [HEADER_CONNECTION_ID]: connectionId,
          [HEADER_SESSION_ID]: sessionId,
        }),
      ).toMatchObject({ status: 202 });

      await readNextSseMessage(sessionEvents);
      await readNextSseMessage(sessionEvents);
      await sessionEvents.return?.();
      await sessionSse.body?.cancel();
    } finally {
      await server.close();
    }
  }, 10_000);

  it("routes permission requests over session SSE and accepts client responses", async () => {
    const server = await startTestServer(() =>
      createTestAgentApp({ enablePermission: true }),
    );

    try {
      const connectionId = await initialize(server.url);
      const sessionId = await createSession(server.url, connectionId);
      const connectionAbort = new AbortController();
      const connectionSse = await openConnectionSse(
        server.url,
        connectionId,
        connectionAbort.signal,
      );
      const sessionSse = await openSessionSse(
        server.url,
        connectionId,
        sessionId,
      );
      const sessionEvents = createSseMessageIterator(sessionSse);

      expect(
        await postJson(server.url, createPromptRequest(3, sessionId), {
          [HEADER_CONNECTION_ID]: connectionId,
          [HEADER_SESSION_ID]: sessionId,
        }),
      ).toMatchObject({ status: 202 });

      expect(await readNextSseMessage(sessionEvents)).toMatchObject({
        jsonrpc: "2.0",
        method: "session/update",
        params: {
          sessionId,
          update: {
            sessionUpdate: "agent_message_chunk",
            content: { text: "chunk-1" },
          },
        },
      });

      const permissionRequest = await readNextSseMessage(sessionEvents);
      expect(permissionRequest).toMatchObject({
        jsonrpc: "2.0",
        id: expect.any(Number),
        method: "session/request_permission",
        params: {
          sessionId,
          toolCall: {
            toolCallId: "permission-tool",
            title: "Permission tool",
          },
          options: expect.arrayContaining([
            expect.objectContaining({
              kind: "allow_once",
              optionId: "allow",
            }),
          ]),
        },
      });
      expect(
        await readNextMessageOrUndefined(connectionSse, connectionAbort),
      ).toBeUndefined();

      expect(
        await postJson(
          server.url,
          {
            jsonrpc: "2.0",
            id: readMessageId(permissionRequest),
            result: {
              outcome: {
                outcome: "selected",
                optionId: "allow",
              },
            },
          },
          {
            [HEADER_CONNECTION_ID]: connectionId,
            [HEADER_SESSION_ID]: sessionId,
          },
        ),
      ).toMatchObject({ status: 202 });

      expect(await readNextSseMessage(sessionEvents)).toMatchObject({
        jsonrpc: "2.0",
        method: "session/update",
        params: {
          sessionId,
          update: {
            sessionUpdate: "agent_message_chunk",
            content: { text: "permission-selected-allow" },
          },
        },
      });
      expect(await readNextSseMessage(sessionEvents)).toMatchObject({
        jsonrpc: "2.0",
        id: 3,
        result: { stopReason: "end_turn" },
      });

      await sessionEvents.return?.();
      await sessionSse.body?.cancel();
    } finally {
      await server.close();
    }
  }, 10_000);
});

async function initialize(url: string): Promise<string> {
  const response = await postJson(url, initializeRequest);
  const connectionId = response.headers.get(HEADER_CONNECTION_ID);

  expect(response.status).toBe(200);
  expect(connectionId).toMatch(/^[0-9a-f-]{36}$/);

  return connectionId ?? "";
}

async function createSession(
  url: string,
  connectionId: string,
): Promise<string> {
  const response = await openConnectionSse(url, connectionId);
  const events = createSseMessageIterator(response);

  try {
    expect(
      await postJson(url, sessionNewRequest, {
        [HEADER_CONNECTION_ID]: connectionId,
      }),
    ).toMatchObject({ status: 202 });

    return readSessionId(await readNextSseMessage(events));
  } finally {
    await events.return?.();
    await response.body?.cancel();
  }
}

function openConnectionSse(
  url: string,
  connectionId: string,
  signal?: AbortSignal,
): Promise<Response> {
  return fetch(url, {
    method: "GET",
    headers: {
      Accept: EVENT_STREAM_MIME_TYPE,
      [HEADER_CONNECTION_ID]: connectionId,
    },
    signal,
  });
}

function openSessionSse(
  url: string,
  connectionId: string,
  sessionId: string,
): Promise<Response> {
  return fetch(url, {
    method: "GET",
    headers: {
      Accept: EVENT_STREAM_MIME_TYPE,
      [HEADER_CONNECTION_ID]: connectionId,
      [HEADER_SESSION_ID]: sessionId,
    },
  });
}

function createSseMessageIterator(
  response: Response,
): AsyncIterator<AnyMessage> {
  if (!response.body) {
    throw new Error("Expected SSE response body");
  }

  return parseSseStream(response.body)[Symbol.asyncIterator]();
}

async function readNextSseMessage(
  iterator: AsyncIterator<AnyMessage>,
): Promise<AnyMessage> {
  const result = await iterator.next();

  if (result.done) {
    throw new Error("Expected SSE message");
  }

  return result.value;
}

async function readNextMessageOrUndefined(
  response: Response,
  abort: AbortController,
): Promise<AnyMessage | undefined> {
  if (!response.body) {
    throw new Error("Expected SSE response body");
  }

  const iterator = parseSseStream(response.body)[Symbol.asyncIterator]();

  try {
    const result = await Promise.race([
      iterator.next(),
      delay(50).then(() => ({ done: true, value: undefined })),
    ]);

    return result.done ? undefined : result.value;
  } finally {
    abort.abort();
    await iterator.return?.();
  }
}

function readMessageId(message: AnyMessage): string | number | null {
  if (!("id" in message)) {
    throw new Error("Expected message ID");
  }

  return message.id;
}

function readSessionId(message: AnyMessage): string {
  if (!("result" in message) || !isRecord(message.result)) {
    throw new Error("Expected session/new response result");
  }

  const sessionId = message.result["sessionId"];

  if (typeof sessionId !== "string") {
    throw new Error("Expected session ID");
  }

  return sessionId;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => {
    setTimeout(resolve, ms);
  });
}

function postJson(
  url: string,
  body: unknown,
  headers: Record<string, string> = {},
): Promise<Response> {
  return fetch(url, {
    method: "POST",
    headers: {
      "Content-Type": JSON_MIME_TYPE,
      ...headers,
    },
    body: JSON.stringify(body),
  });
}

/**
 * Resolves once `condition` holds, checking every few milliseconds, and
 * rejects if it still does not after `timeoutMs`.
 */
export async function until(
  condition: () => boolean,
  timeoutMs = 1_000,
): Promise<void> {
  const deadline = Date.now() + timeoutMs;

  while (!condition()) {
    if (Date.now() > deadline) {
      throw new Error("Timed out waiting for condition");
    }

    await new Promise((resolve) => setTimeout(resolve, 5));
  }
}

import http from "node:http";
import { WebSocketServer } from "ws";

import { AcpServer } from "../server.js";
import {
  createNodeHttpHandler,
  createNodeWebSocketUpgradeHandler,
} from "../node-adapter.js";
import { createTestAgentApp } from "./test-agent.js";

import type { AddressInfo } from "node:net";
import type { AgentApp } from "../acp.js";

export interface TestHttpServer {
  readonly url: string;
  readonly wsUrl: string;
  readonly close: () => Promise<void>;
}

export async function startTestServer(
  createAgent: () => AgentApp = () => createTestAgentApp(),
  options: { port?: number } = {},
): Promise<TestHttpServer> {
  const acpServer = new AcpServer({ createAgent });
  const httpServer = http.createServer(createNodeHttpHandler(acpServer));
  const webSocketServer = new WebSocketServer({ noServer: true });

  httpServer.on(
    "upgrade",
    createNodeWebSocketUpgradeHandler(acpServer, webSocketServer),
  );

  await listen(httpServer, options.port ?? 0);

  const address = httpServer.address();

  if (!isAddressInfo(address)) {
    throw new Error("Test HTTP server did not bind to a TCP port");
  }

  return {
    url: `http://127.0.0.1:${address.port}`,
    wsUrl: `ws://127.0.0.1:${address.port}`,
    close: async () => {
      terminateWebSockets(webSocketServer);
      await Promise.all([
        acpServer.close(),
        closeWebSocketServer(webSocketServer),
        closeHttpServer(httpServer),
      ]);
    },
  };
}

function listen(server: http.Server, port: number): Promise<void> {
  return new Promise((resolve, reject) => {
    const onError = (error: Error): void => {
      server.off("listening", onListening);
      reject(error);
    };

    const onListening = (): void => {
      server.off("error", onError);
      resolve();
    };

    server.once("error", onError);
    server.once("listening", onListening);
    server.listen(port, "127.0.0.1");
  });
}

function terminateWebSockets(server: WebSocketServer): void {
  for (const client of server.clients) {
    client.terminate();
  }
}

function closeWebSocketServer(server: WebSocketServer): Promise<void> {
  return new Promise((resolve, reject) => {
    server.close((error) => {
      if (error) {
        reject(error);
        return;
      }

      resolve();
    });
  });
}

function closeHttpServer(server: http.Server): Promise<void> {
  return new Promise((resolve, reject) => {
    server.close((error) => {
      if (error) {
        reject(error);
        return;
      }

      resolve();
    });
  });
}

function isAddressInfo(
  address: ReturnType<http.Server["address"]>,
): address is AddressInfo {
  return typeof address === "object" && address !== null;
}

const encoder = new TextEncoder();

/** Builds a byte stream that enqueues each chunk and closes. */
export function streamFromChunks(
  chunks: Array<string | Uint8Array>,
): ReadableStream<Uint8Array> {
  return new ReadableStream<Uint8Array>({
    start(controller) {
      for (const chunk of chunks) {
        controller.enqueue(
          typeof chunk === "string" ? encoder.encode(chunk) : chunk,
        );
      }
      controller.close();
    },
  });
}

/** Splits data into fixed-size byte chunks. */
export function chunkBytes(data: string, chunkSize: number): Uint8Array[] {
  if (chunkSize <= 0) {
    throw new RangeError("chunkSize must be positive");
  }
  const bytes = encoder.encode(data);
  const chunks: Uint8Array[] = [];
  for (let i = 0; i < bytes.length; i += chunkSize) {
    chunks.push(bytes.subarray(i, i + chunkSize));
  }
  return chunks;
}

/** Reads a stream to completion, collecting every value. */
export async function collectStream<T>(
  readable: ReadableStream<T>,
): Promise<T[]> {
  const values: T[] = [];
  const reader = readable.getReader();
  try {
    while (true) {
      const { value, done } = await reader.read();
      if (done) {
        break;
      }
      values.push(value);
    }
  } finally {
    reader.releaseLock();
  }
  return values;
}

/** Collects an async iterable to completion. */
export async function collectAll<T>(source: AsyncIterable<T>): Promise<T[]> {
  const values: T[] = [];
  for await (const value of source) {
    values.push(value);
  }
  return values;
}

