#!/usr/bin/env node

import * as acp from "../acp.js";
import { Readable, Writable } from "node:stream";

interface AgentSession {
  pendingPrompt: AbortController | null;
}

class ExampleAgent {
  private sessions: Map<string, AgentSession>;

  constructor() {
    this.sessions = new Map();
  }

  async initialize(
    _params: acp.InitializeRequest,
  ): Promise<acp.InitializeResponse> {
    return {
      protocolVersion: acp.PROTOCOL_VERSION,
      agentCapabilities: {
        loadSession: false,
      },
    };
  }

  async newSession(
    _params: acp.NewSessionRequest,
  ): Promise<acp.NewSessionResponse> {
    const sessionId = Array.from(crypto.getRandomValues(new Uint8Array(16)))
      .map((b) => b.toString(16).padStart(2, "0"))
      .join("");

    this.sessions.set(sessionId, {
      pendingPrompt: null,
    });

    return {
      sessionId,
    };
  }

  async authenticate(
    _params: acp.AuthenticateRequest,
  ): Promise<acp.AuthenticateResponse | void> {
    // No auth needed - return empty response
    return {};
  }

  async setSessionMode(
    _params: acp.SetSessionModeRequest,
  ): Promise<acp.SetSessionModeResponse> {
    // Session mode changes not implemented in this example
    return {};
  }

  async prompt(
    params: acp.PromptRequest,
    cx: acp.AgentContext,
  ): Promise<acp.PromptResponse> {
    const session = this.sessions.get(params.sessionId);

    if (!session) {
      throw new Error(`Session ${params.sessionId} not found`);
    }

    session.pendingPrompt?.abort();
    session.pendingPrompt = new AbortController();

    try {
      await this.simulateTurn(
        params.sessionId,
        session.pendingPrompt.signal,
        cx,
      );
    } catch (err) {
      if (session.pendingPrompt.signal.aborted) {
        return { stopReason: "cancelled" };
      }

      throw err;
    }

    session.pendingPrompt = null;

    return {
      stopReason: "end_turn",
    };
  }

  private async simulateTurn(
    sessionId: string,
    abortSignal: AbortSignal,
    cx: acp.AgentContext,
  ): Promise<void> {
    // Send initial text chunk
    await cx.notify(acp.methods.client.session.update, {
      sessionId,
      update: {
        sessionUpdate: "agent_message_chunk",
        content: {
          type: "text",
          text: "I'll help you with that. Let me start by reading some files to understand the current situation.",
        },
      },
    });

    await this.simulateModelInteraction(abortSignal);

    // Send a tool call that doesn't need permission
    await cx.notify(acp.methods.client.session.update, {
      sessionId,
      update: {
        sessionUpdate: "tool_call",
        toolCallId: "call_1",
        title: "Reading project files",
        kind: "read",
        status: "pending",
        locations: [{ path: "/project/README.md" }],
        rawInput: { path: "/project/README.md" },
      },
    });

    await this.simulateModelInteraction(abortSignal);

    // Update tool call to completed
    await cx.notify(acp.methods.client.session.update, {
      sessionId,
      update: {
        sessionUpdate: "tool_call_update",
        toolCallId: "call_1",
        status: "completed",
        content: [
          {
            type: "content",
            content: {
              type: "text",
              text: "# My Project\n\nThis is a sample project...",
            },
          },
        ],
        rawOutput: { content: "# My Project\n\nThis is a sample project..." },
      },
    });

    await this.simulateModelInteraction(abortSignal);

    // Send more text
    await cx.notify(acp.methods.client.session.update, {
      sessionId,
      update: {
        sessionUpdate: "agent_message_chunk",
        content: {
          type: "text",
          text: " Now I understand the project structure. I need to make some changes to improve it.",
        },
      },
    });

    await this.simulateModelInteraction(abortSignal);

    // Send a tool call that DOES need permission
    await cx.notify(acp.methods.client.session.update, {
      sessionId,
      update: {
        sessionUpdate: "tool_call",
        toolCallId: "call_2",
        title: "Modifying critical configuration file",
        kind: "edit",
        status: "pending",
        locations: [{ path: "/project/config.json" }],
        rawInput: {
          path: "/project/config.json",
          content: '{"database": {"host": "new-host"}}',
        },
      },
    });

    // Request permission for the sensitive operation
    const permissionResponse = await cx.request(
      acp.methods.client.session.requestPermission,
      {
        sessionId,
        toolCall: {
          toolCallId: "call_2",
          title: "Modifying critical configuration file",
          kind: "edit",
          status: "pending",
          locations: [{ path: "/home/user/project/config.json" }],
          rawInput: {
            path: "/home/user/project/config.json",
            content: '{"database": {"host": "new-host"}}',
          },
        },
        options: [
          {
            kind: "allow_once",
            name: "Allow this change",
            optionId: "allow",
          },
          {
            kind: "reject_once",
            name: "Skip this change",
            optionId: "reject",
          },
        ],
      },
    );

    if (permissionResponse.outcome.outcome === "cancelled") {
      return;
    }

    switch (permissionResponse.outcome.optionId) {
      case "allow": {
        await cx.notify(acp.methods.client.session.update, {
          sessionId,
          update: {
            sessionUpdate: "tool_call_update",
            toolCallId: "call_2",
            status: "completed",
            rawOutput: { success: true, message: "Configuration updated" },
          },
        });

        await this.simulateModelInteraction(abortSignal);

        await cx.notify(acp.methods.client.session.update, {
          sessionId,
          update: {
            sessionUpdate: "agent_message_chunk",
            content: {
              type: "text",
              text: " Perfect! I've successfully updated the configuration. The changes have been applied.",
            },
          },
        });
        break;
      }
      case "reject": {
        await this.simulateModelInteraction(abortSignal);

        await cx.notify(acp.methods.client.session.update, {
          sessionId,
          update: {
            sessionUpdate: "agent_message_chunk",
            content: {
              type: "text",
              text: " I understand you prefer not to make that change. I'll skip the configuration update.",
            },
          },
        });
        break;
      }
      default:
        throw new Error(
          `Unexpected permission outcome ${permissionResponse.outcome}`,
        );
    }
  }

  private simulateModelInteraction(abortSignal: AbortSignal): Promise<void> {
    return new Promise((resolve, reject) =>
      setTimeout(() => {
        // In a real agent, you'd pass this abort signal to the LLM client
        if (abortSignal.aborted) {
          reject();
        } else {
          resolve();
        }
      }, 1000),
    );
  }

  async cancel(params: acp.CancelNotification): Promise<void> {
    this.sessions.get(params.sessionId)?.pendingPrompt?.abort();
  }
}

const input = Writable.toWeb(process.stdout);
const output = Readable.toWeb(process.stdin) as ReadableStream<Uint8Array>;

const stream = acp.ndJsonStream(input, output);
const agent = new ExampleAgent();

acp
  .agent({ name: "example-agent" })
  .onRequest("initialize", (ctx) => agent.initialize(ctx.params))
  .onRequest("session/new", (ctx) => agent.newSession(ctx.params))
  .onRequest("authenticate", (ctx) => agent.authenticate(ctx.params))
  .onRequest("session/set_mode", (ctx) => agent.setSessionMode(ctx.params))
  .onRequest("session/prompt", (ctx) => agent.prompt(ctx.params, ctx.client))
  .onNotification("session/cancel", (ctx) => agent.cancel(ctx.params))
  .connect(stream);

#!/usr/bin/env node

/**
 * Experimental example for the draft ACP v2 API.
 *
 * Package consumers must opt in through
 * `@agentclientprotocol/sdk/experimental/v2`. The protocol and API may change
 * incompatibly while ACP v2 remains a draft.
 */

import { Readable, Writable } from "node:stream";

import * as v1 from "../acp.js";
import * as v2 from "../v2/acp.js";

const v1Sessions = new Set<string>();
const v1Agent = v1
  .agent({ name: "dual-version-example-v1" })
  .onRequest(v1.methods.agent.initialize, () => ({
    protocolVersion: v1.PROTOCOL_VERSION,
    agentCapabilities: { loadSession: false },
  }))
  .onRequest(v1.methods.agent.session.new, () => {
    const sessionId = crypto.randomUUID();
    v1Sessions.add(sessionId);
    return { sessionId };
  })
  .onRequest(v1.methods.agent.session.prompt, async ({ params, client }) => {
    requireSession(v1Sessions, params.sessionId);
    await client.notify(v1.methods.client.session.update, {
      sessionId: params.sessionId,
      update: {
        sessionUpdate: "agent_message_chunk",
        content: { type: "text", text: "Hello from the v1 implementation." },
      },
    });
    return { stopReason: "end_turn" };
  })
  .onNotification(v1.methods.agent.session.cancel, () => {});

type V2Turn = {
  controller: AbortController;
  done: Promise<void>;
};

type V2Session = {
  cwd: string;
  active: boolean;
  history: v2.SessionUpdate[];
  state: v2.StateUpdate;
  turn?: V2Turn;
};

const v2Sessions = new Map<string, V2Session>();
const v2Agent = v2
  .agent({ name: "dual-version-example-v2" })
  .onRequest(v2.methods.agent.initialize, () => ({
    protocolVersion: v2.PROTOCOL_VERSION,
    info: { name: "dual-version-example", version: "1.0.0" },
    capabilities: { session: {} },
  }))
  .onRequest(v2.methods.agent.auth.logout, () => {})
  .onRequest(v2.methods.agent.session.new, ({ params }) => {
    const sessionId = crypto.randomUUID();
    v2Sessions.set(sessionId, {
      cwd: params.cwd,
      active: true,
      history: [],
      state: { state: "idle" },
    });
    return { sessionId };
  })
  .onRequest(v2.methods.agent.session.list, ({ params }) => ({
    sessions: [...v2Sessions]
      .filter(([, session]) => params.cwd == null || session.cwd === params.cwd)
      .map(([sessionId, session]) => ({
        sessionId,
        cwd: session.cwd,
      })),
  }))
  .onRequest(v2.methods.agent.session.resume, async ({ params, client }) => {
    const session = requireV2Session(params.sessionId);
    if (session.cwd !== params.cwd) {
      throw v2.RequestError.invalidParams(
        `Session ${params.sessionId} belongs to ${session.cwd}`,
      );
    }

    if (params.replayFrom?.type === "start") {
      for (const update of session.history) {
        await client.notify(v2.methods.client.session.update, {
          sessionId: params.sessionId,
          update,
        });
      }
    } else if (params.replayFrom) {
      throw v2.RequestError.invalidParams(
        `Unsupported replay cursor ${params.replayFrom.type}`,
      );
    }

    session.active = true;
    // Synchronize current state after replay, even when no replay was requested.
    // History contains messages only; historical states are not live activity.
    await client.notify(v2.methods.client.session.update, {
      sessionId: params.sessionId,
      update: { sessionUpdate: "state_update", ...session.state },
    });
    return {};
  })
  .onRequest(v2.methods.agent.session.close, async ({ params }) => {
    const session = requireActiveV2Session(params.sessionId);
    await cancelV2Turn(session);
    session.active = false;
  })
  .onRequest(v2.methods.agent.session.prompt, ({ params, client }) => {
    const session = requireActiveV2Session(params.sessionId);
    if (session.turn) {
      throw v2.RequestError.invalidRequest(
        `Session ${params.sessionId} is already processing a prompt`,
      );
    }

    const controller = new AbortController();
    const turn: V2Turn = {
      controller,
      done: Promise.resolve(),
    };
    const userMessageId = crypto.randomUUID();
    const userMessage: v2.SessionUpdate = {
      sessionUpdate: "user_message",
      messageId: userMessageId,
      content: params.prompt,
    };
    session.history.push(userMessage);

    // The framework queues the prompt response after this handler returns.
    // The user message is already inserted; start notifications and processing
    // in the next event-loop task so the insertion receipt is queued first.
    const responseQueued = new Promise<void>((resolve) => {
      setTimeout(resolve, 0);
    });
    turn.done = responseQueued
      .then(() =>
        runV2Turn(params, client, session, controller.signal, userMessage),
      )
      .catch((error) => {
        // Completion could not be delivered, for example after a transport failure.
        console.error("v2 example could not report turn completion", error);
      })
      .finally(() => {
        if (session.turn === turn) {
          session.turn = undefined;
        }
      });
    session.turn = turn;
    return { messageId: userMessageId };
  })
  .onNotification(v2.methods.agent.session.cancel, async ({ params }) => {
    await cancelV2Turn(requireActiveV2Session(params.sessionId));
  });

const output = Writable.toWeb(process.stdout);
const input = Readable.toWeb(process.stdin) as ReadableStream<Uint8Array>;
const stream = v1.ndJsonStream(output, input);

v2.agentProtocolRouter().withV1(v1Agent).withV2(v2Agent).connect(stream);

function requireSession(sessions: Set<string>, sessionId: string): void {
  if (!sessions.has(sessionId)) {
    throw new Error(`Session ${sessionId} not found`);
  }
}

function requireV2Session(sessionId: string): V2Session {
  const session = v2Sessions.get(sessionId);
  if (!session) {
    throw v2.RequestError.invalidParams(`Session ${sessionId} not found`);
  }
  return session;
}

function requireActiveV2Session(sessionId: string): V2Session {
  const session = requireV2Session(sessionId);
  if (!session.active) {
    throw v2.RequestError.invalidParams(`Session ${sessionId} is not active`);
  }
  return session;
}

async function cancelV2Turn(session: V2Session): Promise<void> {
  const turn = session.turn;
  if (!turn) {
    return;
  }

  turn.controller.abort();
  await turn.done;
}

function waitForWork(signal: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal.aborted) {
      reject(signal.reason);
      return;
    }

    const onAbort = () => {
      clearTimeout(timeout);
      reject(signal.reason);
    };
    const timeout = setTimeout(() => {
      signal.removeEventListener("abort", onAbort);
      resolve();
    }, 250);
    signal.addEventListener("abort", onAbort, { once: true });
  });
}

async function runV2Turn(
  params: v2.PromptRequest,
  client: v2.AgentContext,
  session: V2Session,
  signal: AbortSignal,
  userMessage: v2.SessionUpdate,
): Promise<void> {
  try {
    await client.notify(v2.methods.client.session.update, {
      sessionId: params.sessionId,
      update: userMessage,
    });

    signal.throwIfAborted();
    session.state = { state: "running" };
    await client.notify(v2.methods.client.session.update, {
      sessionId: params.sessionId,
      update: { sessionUpdate: "state_update", ...session.state },
    });
    await waitForWork(signal);

    signal.throwIfAborted();
    const agentMessage: v2.SessionUpdate = {
      sessionUpdate: "agent_message",
      messageId: crypto.randomUUID(),
      content: [{ type: "text", text: "Hello from the v2 implementation." }],
    };
    session.history.push(agentMessage);
    await client.notify(v2.methods.client.session.update, {
      sessionId: params.sessionId,
      update: agentMessage,
    });

    signal.throwIfAborted();
    session.state = { state: "idle", stopReason: "end_turn" };
    await client.notify(v2.methods.client.session.update, {
      sessionId: params.sessionId,
      update: { sessionUpdate: "state_update", ...session.state },
    });
  } catch (error) {
    // Insertion already succeeded. Report failures on idle, not on the prompt RPC.
    const completion: v2.IdleStateUpdate = signal.aborted
      ? { stopReason: "cancelled" }
      : {
          stopReason: "error",
          error: (error instanceof v2.RequestError
            ? error
            : v2.RequestError.internalError(
                undefined,
                error instanceof Error ? error.message : undefined,
              )
          ).toErrorResponse(),
        };

    session.state = { state: "idle", ...completion };
    await client.notify(v2.methods.client.session.update, {
      sessionId: params.sessionId,
      update: { sessionUpdate: "state_update", ...session.state },
    });
  }
}

import { describe, expect, it } from "vitest";

import { onWebSocket, webSocketMessageToString } from "./ws-utils.js";

describe("webSocketMessageToString", () => {
  it("accepts only WebSocket text message payloads", () => {
    expect(webSocketMessageToString(["text"])).toBe("text");
    expect(webSocketMessageToString([{ data: "event text" }])).toBe(
      "event text",
    );
    expect(
      webSocketMessageToString([new TextEncoder().encode("binary text")]),
    ).toBe(undefined);
    expect(
      webSocketMessageToString([
        new TextEncoder().encode("binary text").buffer,
      ]),
    ).toBe(undefined);
    expect(
      webSocketMessageToString([[new TextEncoder().encode("binary text")]]),
    ).toBe(undefined);
  });
});

describe("onWebSocket", () => {
  it("normalizes Node ws text frames before shared message parsing", () => {
    const socket = new EventEmitterWebSocket();
    const messages: Array<string | undefined> = [];

    onWebSocket(socket, "message", (...args) => {
      messages.push(webSocketMessageToString(args));
    });

    socket.emit("message", new TextEncoder().encode("text frame"), false);
    socket.emit("message", new TextEncoder().encode("binary frame"), true);

    expect(messages).toEqual(["text frame", undefined]);
  });
});

class EventEmitterWebSocket {
  private readonly listeners = new Map<
    string,
    Set<(...args: unknown[]) => void>
  >();

  send(): void {}

  close(): void {}

  on(type: string, listener: (...args: unknown[]) => void): void {
    this.listeners.set(
      type,
      (this.listeners.get(type) ?? new Set()).add(listener),
    );
  }

  off(type: string, listener: (...args: unknown[]) => void): void {
    this.listeners.get(type)?.delete(listener);
  }

  emit(type: string, ...args: unknown[]): void {
    this.listeners.get(type)?.forEach((listener) => {
      listener(...args);
    });
  }
}

import { describe, expect, it } from "vitest";

import { MemoryAcpCookieStore } from "./cookie-store.js";

describe("MemoryAcpCookieStore", () => {
  it("stores single and multiple Set-Cookie values", () => {
    const store = new MemoryAcpCookieStore();
    store.store(headersWithSetCookie(["transport=alpha; Path=/"]));
    store.store(
      headersWithSetCookie(["route=bravo; Path=/", "affinity=charlie"]),
    );

    const headers = new Headers();
    store.apply(headers);

    expect(headers.get("Cookie")).toBe(
      "transport=alpha; route=bravo; affinity=charlie",
    );
  });

  it("splits combined Set-Cookie headers with Expires commas", () => {
    const store = new MemoryAcpCookieStore();
    store.store(
      new Headers({
        "Set-Cookie":
          "transport=alpha; Expires=Wed, 21 Oct 2030 07:28:00 GMT, route=bravo; Path=/",
      }),
    );

    const headers = new Headers();
    store.apply(headers);

    expect(headers.get("Cookie")).toBe("transport=alpha; route=bravo");
  });

  it("ignores malformed cookie headers", () => {
    const store = new MemoryAcpCookieStore();
    store.store(
      headersWithSetCookie([
        "missing-separator",
        "=empty-name",
        " =blank",
        "ok=value",
      ]),
    );

    const headers = new Headers();
    store.apply(headers);

    expect(headers.get("Cookie")).toBe("ok=value");
  });

  it("lets later cookies overwrite earlier cookies with the same name", () => {
    const store = new MemoryAcpCookieStore();
    store.store(headersWithSetCookie(["route=alpha", "route=bravo"]));

    const headers = new Headers();
    store.apply(headers);

    expect(headers.get("Cookie")).toBe("route=bravo");
  });

  it("writes a Cookie header when managed cookies exist", () => {
    const store = new MemoryAcpCookieStore();
    store.store(headersWithSetCookie(["transport=alpha"]));

    const headers = new Headers();
    store.apply(headers);

    expect(headers.get("Cookie")).toBe("transport=alpha");
  });

  it("merges managed cookies with caller-provided Cookie headers", () => {
    const store = new MemoryAcpCookieStore();
    store.store(headersWithSetCookie(["transport=alpha", "route=bravo"]));

    const headers = new Headers({ Cookie: "caller=custom" });
    store.apply(headers);

    expect(headers.get("Cookie")).toBe(
      "transport=alpha; route=bravo; caller=custom",
    );
  });

  it("lets caller-provided cookie values override managed duplicate names", () => {
    const store = new MemoryAcpCookieStore();
    store.store(headersWithSetCookie(["transport=alpha", "route=bravo"]));

    const headers = new Headers({ Cookie: "route=caller; caller=custom" });
    store.apply(headers);

    expect(headers.get("Cookie")).toBe(
      "transport=alpha; route=caller; caller=custom",
    );
  });

  it("clears managed cookies", () => {
    const store = new MemoryAcpCookieStore();
    store.store(headersWithSetCookie(["transport=alpha"]));
    store.clear();

    const headers = new Headers();
    store.apply(headers);

    expect(headers.get("Cookie")).toBeNull();
  });
});

function headersWithSetCookie(values: readonly string[]): Headers {
  const headers = new Headers();

  Object.defineProperty(headers, "getSetCookie", {
    value: () => values,
  });

  return headers;
}

import { describe, it, expect } from "vitest";
import { LineBuffer } from "./line-buffer.js";

const encoder = new TextEncoder();
const decoder = new TextDecoder();

function pushAll(buffer: LineBuffer, chunks: string[]): string[] {
  const lines: string[] = [];
  for (const chunk of chunks) {
    for (const line of buffer.push(encoder.encode(chunk))) {
      lines.push(decoder.decode(line));
    }
  }
  return lines;
}

describe("LineBuffer", () => {
  it("splits complete lines within one chunk", () => {
    const buffer = new LineBuffer();

    expect(pushAll(buffer, ["a\nbb\nccc\n"])).toEqual(["a", "bb", "ccc"]);
    expect(buffer.flush()).toBeUndefined();
  });

  it("carries an incomplete line across chunks", () => {
    const buffer = new LineBuffer();

    expect(pushAll(buffer, ["ab", "cd ef", "gh\nnext"])).toEqual(["abcd efgh"]);
    expect(decoder.decode(buffer.flush())).toBe("next");
  });

  it("handles a newline at a chunk boundary", () => {
    const buffer = new LineBuffer();

    expect(pushAll(buffer, ["one", "\ntwo\n"])).toEqual(["one", "two"]);
    expect(buffer.flush()).toBeUndefined();
  });

  it("yields empty lines", () => {
    const buffer = new LineBuffer();

    expect(pushAll(buffer, ["a\n\nb\n"])).toEqual(["a", "", "b"]);
  });

  it("flushes a trailing unterminated line once", () => {
    const buffer = new LineBuffer();

    expect(pushAll(buffer, ["tail"])).toEqual([]);
    expect(decoder.decode(buffer.flush())).toBe("tail");
    expect(buffer.flush()).toBeUndefined();
  });

  it("handles empty chunks", () => {
    const buffer = new LineBuffer();

    expect(pushAll(buffer, ["", "a", "", "\n"])).toEqual(["a"]);
  });
});

import { describe, expect, it, vi } from "vitest";

import {
  parseSseStream,
  serializeSseEvent,
  serializeSseKeepAlive,
} from "./sse.js";

import type { AnyMessage } from "./jsonrpc.js";
import {
  chunkBytes,
  collectAll,
  streamFromChunks,
} from "./test-support/streams.js";

function collectMessages(
  body: ReadableStream<Uint8Array>,
): Promise<AnyMessage[]> {
  return collectAll(parseSseStream(body));
}

describe("SSE transport helpers", () => {
  it("serializes a message event", () => {
    const message: AnyMessage = {
      jsonrpc: "2.0",
      id: 1,
      method: "initialize",
      params: { protocolVersion: 1 },
    };

    expect(serializeSseEvent(message)).toBe(
      `data: ${JSON.stringify(message)}\n\n`,
    );
  });

  it("serializes a keepalive comment", () => {
    expect(serializeSseKeepAlive()).toBe(":\n\n");
  });

  it("parses one event", async () => {
    const message: AnyMessage = { jsonrpc: "2.0", id: 1, result: { ok: true } };

    await expect(
      collectMessages(streamFromChunks([serializeSseEvent(message)])),
    ).resolves.toEqual([message]);
  });

  it("passes through a response batch as one event", async () => {
    const batch = [
      { jsonrpc: "2.0", id: 1, result: { value: 1 } },
      { jsonrpc: "2.0", id: 2, result: { value: 2 } },
    ];

    await expect(
      collectMessages(
        streamFromChunks([serializeSseEvent(batch as unknown as AnyMessage)]),
      ),
    ).resolves.toEqual([batch]);
  });

  it("parses multiple events in one chunk", async () => {
    const first: AnyMessage = { jsonrpc: "2.0", id: 1, result: { ok: true } };
    const second: AnyMessage = {
      jsonrpc: "2.0",
      method: "session/update",
      params: { sessionId: "s1" },
    };

    await expect(
      collectMessages(
        streamFromChunks([
          serializeSseEvent(first) + serializeSseEvent(second),
        ]),
      ),
    ).resolves.toEqual([first, second]);
  });

  it("parses events split across chunk boundaries", async () => {
    const message: AnyMessage = {
      jsonrpc: "2.0",
      id: "abc",
      result: { ok: true },
    };
    const serialized = serializeSseEvent(message);

    await expect(
      collectMessages(
        streamFromChunks([
          serialized.slice(0, 7),
          serialized.slice(7, 18),
          serialized.slice(18),
        ]),
      ),
    ).resolves.toEqual([message]);
  });

  it("ignores comments, keepalives, and non-data fields", async () => {
    const message: AnyMessage = { jsonrpc: "2.0", id: 1, result: { ok: true } };

    await expect(
      collectMessages(
        streamFromChunks([
          `:\n\nevent: message\nid: 1\ndata: ${JSON.stringify(message)}\nretry: 1000\n\n`,
        ]),
      ),
    ).resolves.toEqual([message]);
  });

  it("joins multiline data fields", async () => {
    const expected: AnyMessage = {
      jsonrpc: "2.0",
      id: 1,
      result: { ok: true },
    };
    const body = [
      'data: {"jsonrpc":"2.0",\n',
      'data: "id":1,\n',
      'data: "result":{"ok":true}}\n\n',
    ];

    await expect(collectMessages(streamFromChunks(body))).resolves.toEqual([
      expected,
    ]);
  });

  it("parses a large event spanning many chunks", async () => {
    const message: AnyMessage = {
      jsonrpc: "2.0",
      method: "session/update",
      params: { data: "héllo wörld ".repeat(10_000) },
    };
    const chunks = chunkBytes(serializeSseEvent(message), 1024);
    expect(chunks.length).toBeGreaterThan(100);

    await expect(collectMessages(streamFromChunks(chunks))).resolves.toEqual([
      message,
    ]);
  });

  it("parses events separated by CRLF blank lines", async () => {
    const first: AnyMessage = { jsonrpc: "2.0", id: 1, result: { ok: true } };
    const second: AnyMessage = {
      jsonrpc: "2.0",
      method: "session/update",
      params: { sessionId: "s1" },
    };
    const body =
      `data: ${JSON.stringify(first)}\r\n\r\n` +
      `data: ${JSON.stringify(second)}\r\n\r\n`;

    await expect(collectMessages(streamFromChunks([body]))).resolves.toEqual([
      first,
      second,
    ]);
  });

  it("parses a final event without a trailing blank line", async () => {
    const message: AnyMessage = { jsonrpc: "2.0", id: 1, result: { ok: true } };

    await expect(
      collectMessages(streamFromChunks([`data: ${JSON.stringify(message)}\n`])),
    ).resolves.toEqual([message]);
  });

  it("passes through object payloads without validating their shape", async () => {
    // Lenient shapes are left for the connection layer to validate.
    const lenient = { id: 1, result: { ok: true } }; // missing jsonrpc
    await expect(
      collectMessages(
        streamFromChunks([`data: ${JSON.stringify(lenient)}\n\n`]),
      ),
    ).resolves.toEqual([lenient]);
  });

  it("skips non-object payloads", async () => {
    const warn = vi.spyOn(console, "warn").mockImplementation(() => undefined);
    const message: AnyMessage = { jsonrpc: "2.0", id: 1, result: { ok: true } };

    await expect(
      collectMessages(
        streamFromChunks(["data: 42\n\n", serializeSseEvent(message)]),
      ),
    ).resolves.toEqual([message]);
    expect(warn).toHaveBeenCalledOnce();

    warn.mockRestore();
  });

  it("skips malformed JSON without throwing", async () => {
    const warn = vi.spyOn(console, "warn").mockImplementation(() => undefined);
    const message: AnyMessage = { jsonrpc: "2.0", id: 1, result: { ok: true } };

    await expect(
      collectMessages(
        streamFromChunks(["data: {not-json}\n\n", serializeSseEvent(message)]),
      ),
    ).resolves.toEqual([message]);
    expect(warn).toHaveBeenCalledOnce();

    warn.mockRestore();
  });
});

import { describe, expect, it } from "vitest";
import { z } from "zod/v4";

import {
  excludeKnownTags,
  preserveCustomPayload,
} from "./schema-deserialize.js";

describe("excludeKnownTags", () => {
  const catchAll = excludeKnownTags(z.object({ mode: z.string() }), "mode", [
    "form",
    "url",
  ]);

  it("accepts values with a custom tag", () => {
    expect(catchAll.safeParse({ mode: "_vendor" }).success).toBe(true);
  });

  it("rejects values whose tag is reserved by a known variant", () => {
    const result = catchAll.safeParse({ mode: "form" });
    expect(result.success).toBe(false);
    if (!result.success) {
      // The issue names the offending tag and points at the discriminant, so
      // union-level errors (which surface only this issue) stay actionable.
      expect(result.error.issues).toHaveLength(1);
      expect(result.error.issues[0]).toMatchObject({
        code: "custom",
        path: ["mode"],
      });
      expect(result.error.issues[0].message).toContain('"form"');
    }
  });
});

describe("preserveCustomPayload", () => {
  const inner = z.union([
    z.object({ mode: z.literal("form"), value: z.number() }),
    excludeKnownTags(z.object({ mode: z.string() }), "mode", ["form"]),
  ]);
  const schema = preserveCustomPayload(inner, "mode", ["form"]);

  it("re-attaches unevaluated keys for custom-tagged values", () => {
    const result = schema.parse({ mode: "_vendor", payload: { x: 1 } });
    expect(result).toEqual({ mode: "_vendor", payload: { x: 1 } });
  });

  it("re-attaches payload keys that shadow Object.prototype members", () => {
    // `in`-style presence checks see inherited members; the re-attach must
    // use an own-key check or these vendor keys silently vanish.
    const result = schema.parse(
      JSON.parse('{"mode":"_vendor","constructor":"tag","toString":"x"}'),
    ) as Record<string, unknown>;
    expect(Object.hasOwn(result, "constructor")).toBe(true);
    expect(result.constructor).toBe("tag");
    expect(result.toString).toBe("x");
  });

  it("never re-attaches __proto__", () => {
    const result = schema.parse(
      JSON.parse('{"mode":"_vendor","__proto__":{"polluted":true}}'),
    ) as Record<string, unknown>;
    expect(Object.hasOwn(result, "__proto__")).toBe(false);
    expect((result as { polluted?: unknown }).polluted).toBeUndefined();
    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
  });

  it("does not re-attach keys for known-tagged values", () => {
    const result = schema.parse({ mode: "form", value: 1, extra: "dropped" });
    expect(result).toEqual({ mode: "form", value: 1 });
  });

  it("skips re-attachment when the tag is not a string", () => {
    const lax = preserveCustomPayload(z.object({ other: z.string() }), "mode", [
      "form",
    ]);
    expect(lax.parse({ other: "x", extra: 1 })).toEqual({ other: "x" });
  });

  it("passes non-object values through the inner schema untouched", () => {
    const passthrough = preserveCustomPayload(z.string(), "mode", ["form"]);
    expect(passthrough.parse("plain")).toBe("plain");
  });

  it("forwards the inner schema's issues with their paths on failure", () => {
    const result = schema.safeParse({ mode: "form", value: "not-a-number" });
    expect(result.success).toBe(false);
    if (!result.success) {
      expect(result.error.issues.length).toBeGreaterThan(0);
      const paths = result.error.issues.map((issue: z.core.$ZodIssue) =>
        issue.path.join("."),
      );
      expect(paths).toContain("mode");
    }
  });

  it("keeps keys the winning member evaluated, even when salvaged", () => {
    // Keys evaluated by the winning member keep their parsed results; keys
    // only a LOSING member would have salvaged arrive raw. This asymmetry is
    // faithful to the schema's unevaluatedProperties semantics — this test
    // pins it so a change is a conscious decision.
    const salvaging = preserveCustomPayload(
      z.union([
        z.object({ mode: z.literal("form"), meta: z.number().catch(0) }),
        excludeKnownTags(z.object({ mode: z.string() }), "mode", ["form"]),
      ]),
      "mode",
      ["form"],
    );
    expect(salvaging.parse({ mode: "form", meta: "bad" })).toEqual({
      mode: "form",
      meta: 0,
    });
    expect(salvaging.parse({ mode: "_vendor", meta: "raw" })).toEqual({
      mode: "_vendor",
      meta: "raw",
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { ndJsonStream } from "./stream.js";
import type { AnyWireMessage } from "./jsonrpc.js";
import {
  chunkBytes,
  collectStream,
  streamFromChunks,
} from "./test-support/streams.js";

describe("ndJsonStream", () => {
  const nullWritable = new WritableStream<Uint8Array>();

  it("parses a single message", async () => {
    const msg = { jsonrpc: "2.0" as const, id: 1, method: "test" };
    const input = streamFromChunks([JSON.stringify(msg) + "\n"]);

    const { readable } = ndJsonStream(nullWritable, input);
    const messages = await collectStream(readable);

    expect(messages).toEqual([msg]);
  });

  it("parses multiple messages", async () => {
    const msg1 = { jsonrpc: "2.0" as const, id: 1, method: "first" };
    const msg2 = { jsonrpc: "2.0" as const, id: 2, method: "second" };
    const input = streamFromChunks([
      JSON.stringify(msg1) + "\n" + JSON.stringify(msg2) + "\n",
    ]);

    const { readable } = ndJsonStream(nullWritable, input);
    const messages = await collectStream(readable);

    expect(messages).toEqual([msg1, msg2]);
  });

  it("passes through a JSON-RPC batch as one transport message", async () => {
    const batch = [
      { jsonrpc: "2.0" as const, id: 1, method: "first" },
      { jsonrpc: "2.0" as const, method: "notify" },
    ];
    const input = streamFromChunks([JSON.stringify(batch) + "\n"]);

    const { readable } = ndJsonStream<AnyWireMessage>(nullWritable, input);
    const messages = await collectStream(readable);

    expect(messages).toEqual([batch]);
  });

  it("writes a JSON-RPC batch as one NDJSON line", async () => {
    const chunks: Uint8Array[] = [];
    const output = new WritableStream<Uint8Array>({
      write(chunk) {
        chunks.push(chunk);
      },
    });
    const input = new ReadableStream<Uint8Array>({
      start(controller) {
        controller.close();
      },
    });
    const batch = [
      { jsonrpc: "2.0" as const, id: 1, method: "first" },
      { jsonrpc: "2.0" as const, method: "notify" },
    ] as const;
    const { writable } = ndJsonStream<AnyWireMessage>(output, input);
    const writer = writable.getWriter();

    await writer.write(batch);
    writer.releaseLock();

    expect(new TextDecoder().decode(chunks[0])).toBe(
      JSON.stringify(batch) + "\n",
    );
  });

  it("parses a message split across chunks", async () => {
    const msg = { jsonrpc: "2.0" as const, id: 1, method: "split" };
    const full = JSON.stringify(msg) + "\n";
    const mid = Math.floor(full.length / 2);

    const input = streamFromChunks([full.slice(0, mid), full.slice(mid)]);

    const { readable } = ndJsonStream(nullWritable, input);
    const messages = await collectStream(readable);

    expect(messages).toEqual([msg]);
  });

  it("parses a large message spanning many chunks", async () => {
    const msg = {
      jsonrpc: "2.0" as const,
      id: 1,
      method: "large",
      params: { data: "héllo wörld ".repeat(10_000) },
    };
    const chunks = chunkBytes(JSON.stringify(msg) + "\n", 1024);
    expect(chunks.length).toBeGreaterThan(100);

    const { readable } = ndJsonStream(nullWritable, streamFromChunks(chunks));
    const messages = await collectStream(readable);

    expect(messages).toEqual([msg]);
  });

  it("parses messages when chunk boundaries fall mid-message", async () => {
    const msg1 = { jsonrpc: "2.0" as const, id: 1, method: "first" };
    const msg2 = { jsonrpc: "2.0" as const, id: 2, method: "second" };
    const msg3 = { jsonrpc: "2.0" as const, id: 3, method: "third" };
    const full = [msg1, msg2, msg3]
      .map((m) => JSON.stringify(m) + "\n")
      .join("");

    // One chunk ends with a complete message plus the start of the next.
    const cut = full.indexOf('"second"');
    const input = streamFromChunks([full.slice(0, cut), full.slice(cut)]);

    const { readable } = ndJsonStream(nullWritable, input);
    const messages = await collectStream(readable);

    expect(messages).toEqual([msg1, msg2, msg3]);
  });

  it("handles multi-byte UTF-8 characters split across chunks", async () => {
    const msg = {
      jsonrpc: "2.0" as const,
      id: 1,
      method: "test",
      params: { text: "héllo wörld" },
    };
    const bytes = new TextEncoder().encode(JSON.stringify(msg) + "\n");

    // Find the byte offset of 'é' (0xC3 0xA9) and split between its two bytes
    const éOffset = bytes.indexOf(0xc3);
    expect(éOffset).toBeGreaterThan(0);

    const input = streamFromChunks([
      bytes.slice(0, éOffset + 1), // includes 0xC3 but not 0xA9
      bytes.slice(éOffset + 1), // starts with 0xA9
    ]);

    const { readable } = ndJsonStream(nullWritable, input);
    const messages = await collectStream(readable);

    expect(messages).toEqual([msg]);
  });

  it("parses a final message without trailing newline", async () => {
    const msg = { jsonrpc: "2.0" as const, id: 1, method: "unterminated" };
    const input = streamFromChunks([JSON.stringify(msg)]); // no \n

    const { readable } = ndJsonStream(nullWritable, input);
    const messages = await collectStream(readable);

    expect(messages).toEqual([msg]);
  });

  it("parses a final message without trailing newline with multi-byte chars split across chunks", async () => {
    const msg = {
      jsonrpc: "2.0" as const,
      id: 1,
      method: "tëst",
    };
    const bytes = new TextEncoder().encode(JSON.stringify(msg)); // no \n
    const éOffset = bytes.indexOf(0xc3);
    expect(éOffset).toBeGreaterThan(0);

    const input = streamFromChunks([
      bytes.slice(0, éOffset + 1), // includes 0xC3 but not 0xAB
      bytes.slice(éOffset + 1),
    ]);

    const { readable } = ndJsonStream(nullWritable, input);
    const messages = await collectStream(readable);

    expect(messages).toEqual([msg]);
  });

  it("responds to malformed and primitive lines and continues parsing", async () => {
    const outputChunks: Uint8Array[] = [];
    const output = new WritableStream<Uint8Array>({
      write(chunk) {
        outputChunks.push(chunk);
      },
    });
    const msg = { jsonrpc: "2.0" as const, id: 2, method: "after" };
    const input = streamFromChunks([
      "not valid json\n42\n\n" + JSON.stringify(msg) + "\n",
    ]);

    const { readable } = ndJsonStream(output, input);
    const messages = await collectStream(readable);
    const responses = outputChunks
      .map((chunk) => new TextDecoder().decode(chunk))
      .join("")
      .trim()
      .split("\n")
      .map((line) => JSON.parse(line));

    expect(messages).toEqual([msg]);
    expect(responses).toMatchObject([
      { jsonrpc: "2.0", id: null, error: { code: -32700 } },
      { jsonrpc: "2.0", id: null, error: { code: -32600 } },
    ]);
  });

  it("passes through object messages without validating their shape", async () => {
    // Lenient peers may omit the jsonrpc field or send unusual response
    // shapes; the connection layer decides how to handle them.
    const lenient = { id: 1, method: "initialize", params: {} };
    const bothMembers = {
      jsonrpc: "2.0" as const,
      id: 2,
      result: {},
      error: null,
    };
    const input = streamFromChunks([
      JSON.stringify(lenient) + "\n" + JSON.stringify(bothMembers) + "\n",
    ]);

    const { readable } = ndJsonStream(nullWritable, input);
    const messages = await collectStream(readable);

    expect(messages).toEqual([lenient, bothMembers]);
  });

  it("cancels the underlying input reader when canceled", async () => {
    const { promise: canceled, resolve: resolveCanceled } =
      Promise.withResolvers<unknown>();
    const input = new ReadableStream<Uint8Array>({
      cancel(reason) {
        resolveCanceled(reason);
      },
    });
    const reason = new Error("connection closed");
    const { readable } = ndJsonStream(nullWritable, input);
    const reader = readable.getReader();

    await reader.cancel(reason);
    reader.releaseLock();

    await expect(canceled).resolves.toBe(reason);
    await vi.waitFor(() => {
      const inputReader = input.getReader();
      inputReader.releaseLock();
    });
  });
});

import { describe, expect, it } from "vitest";

import { AGENT_METHODS } from "./schema/index.js";
import {
  methodRequiresSessionHeader,
  sessionIdFromParams,
  isInitializeRequest,
  messageIdKey,
  HEADER_CONNECTION_ID,
  HEADER_SESSION_ID,
  EVENT_STREAM_MIME_TYPE,
  JSON_MIME_TYPE,
} from "./protocol.js";

import type { AnyMessage } from "./jsonrpc.js";

describe("protocol transport helpers", () => {
  it("exports HTTP transport constants", () => {
    expect(HEADER_CONNECTION_ID).toBe("Acp-Connection-Id");
    expect(HEADER_SESSION_ID).toBe("Acp-Session-Id");
    expect(EVENT_STREAM_MIME_TYPE).toBe("text/event-stream");
    expect(JSON_MIME_TYPE).toBe("application/json");
  });

  it("requires a session header for existing-session methods", () => {
    expect(methodRequiresSessionHeader(AGENT_METHODS.session_cancel)).toBe(
      true,
    );
    expect(methodRequiresSessionHeader(AGENT_METHODS.session_close)).toBe(true);
    expect(methodRequiresSessionHeader(AGENT_METHODS.session_delete)).toBe(
      true,
    );
    expect(methodRequiresSessionHeader(AGENT_METHODS.session_fork)).toBe(true);
    expect(methodRequiresSessionHeader(AGENT_METHODS.session_load)).toBe(true);
    expect(methodRequiresSessionHeader(AGENT_METHODS.session_prompt)).toBe(
      true,
    );
    expect(methodRequiresSessionHeader(AGENT_METHODS.session_resume)).toBe(
      true,
    );
    expect(
      methodRequiresSessionHeader(AGENT_METHODS.session_set_config_option),
    ).toBe(true);
    expect(methodRequiresSessionHeader(AGENT_METHODS.session_set_mode)).toBe(
      true,
    );
    expect(methodRequiresSessionHeader("session/set_model")).toBe(true);
  });

  it("does not require a session header for connection-level methods", () => {
    expect(methodRequiresSessionHeader(AGENT_METHODS.initialize)).toBe(false);
    expect(methodRequiresSessionHeader(AGENT_METHODS.session_new)).toBe(false);
    expect(methodRequiresSessionHeader(AGENT_METHODS.session_list)).toBe(false);
  });

  it("extracts a top-level string session ID from params", () => {
    expect(sessionIdFromParams({ sessionId: "session-1" })).toBe("session-1");
  });

  it("returns undefined when params do not contain a top-level string session ID", () => {
    expect(sessionIdFromParams(undefined)).toBeUndefined();
    expect(sessionIdFromParams(null)).toBeUndefined();
    expect(sessionIdFromParams("session-1")).toBeUndefined();
    expect(sessionIdFromParams({})).toBeUndefined();
    expect(sessionIdFromParams({ sessionId: 1 })).toBeUndefined();
    expect(
      sessionIdFromParams({ nested: { sessionId: "session-1" } }),
    ).toBeUndefined();
  });

  it("detects initialize requests", () => {
    const request: AnyMessage = {
      jsonrpc: "2.0",
      id: 1,
      method: AGENT_METHODS.initialize,
      params: { protocolVersion: 1, clientCapabilities: {} },
    };

    expect(isInitializeRequest(request)).toBe(true);
  });

  it("rejects non-initialize messages", () => {
    const notification: AnyMessage = {
      jsonrpc: "2.0",
      method: AGENT_METHODS.initialize,
      params: { protocolVersion: 1, clientCapabilities: {} },
    };
    const response: AnyMessage = { jsonrpc: "2.0", id: 1, result: {} };
    const otherRequest: AnyMessage = {
      jsonrpc: "2.0",
      id: 1,
      method: AGENT_METHODS.session_new,
      params: { cwd: "/tmp", mcpServers: [] },
    };

    expect(isInitializeRequest(notification)).toBe(false);
    expect(isInitializeRequest(response)).toBe(false);
    expect(isInitializeRequest(otherRequest)).toBe(false);
  });

  it("normalizes JSON-RPC request IDs for map keys", () => {
    expect(messageIdKey("foo")).toBe("string:foo");
    expect(messageIdKey(1)).toBe("number:1");
    expect(messageIdKey(null)).toBe("null");
    expect(messageIdKey(undefined)).toBeUndefined();
  });
});

import { describe, expect, it, vi } from "vitest";

import { OutboundMailbox } from "./connection.js";
import { createSseBody, createSseBodySource } from "./server-sse.js";
import { serializeSseEvent, serializeSseKeepAlive } from "./sse.js";

import type { AnyMessage } from "./jsonrpc.js";

const message = {
  jsonrpc: "2.0",
  id: 1,
  result: {
    ok: true,
  },
} satisfies AnyMessage;

describe("createSseBodySource", () => {
  it("enqueues a subscription message after it has been read even if demand changed", async () => {
    const mailbox = new OutboundMailbox<string>();
    const lease = mailbox.tryAcquire();
    if (!lease) {
      throw new Error("Expected outbound mailbox lease");
    }
    const source = createSseBodySource(lease);
    const enqueued: Uint8Array[] = [];
    let desiredSize: number | null = 1;
    const controller = {
      get desiredSize() {
        return desiredSize;
      },
      enqueue(chunk: Uint8Array) {
        enqueued.push(chunk);
      },
      close() {
        return undefined;
      },
      error(error?: unknown) {
        if (error) {
          throw error;
        }
      },
    } as ReadableStreamDefaultController<Uint8Array>;

    await source.pull?.(controller);
    await flushMicrotasks();
    desiredSize = 0;

    mailbox.push(JSON.stringify(message));
    await new Promise((resolve) => setTimeout(resolve, 0));

    expect(enqueued.map(decodeText)).toEqual([serializeSseEvent(message)]);
  });
});

describe("createSseBody", () => {
  it("leaves messages queued until its reader asks for one", async () => {
    const mailbox = new OutboundMailbox<string>();
    const lease = mailbox.tryAcquire();
    if (!lease) {
      throw new Error("Expected outbound mailbox lease");
    }
    const reader = createSseBody(lease).getReader();

    mailbox.push(JSON.stringify(message));
    await flushMicrotasks();
    expect(mailbox.hasQueuedMessages).toBe(true);

    const { value } = await reader.read();
    expect(value && decodeText(value)).toBe(serializeSseEvent(message));
    expect(mailbox.hasQueuedMessages).toBe(false);
    await reader.cancel();
  });

  it("ends cleanly when its stream shuts down while the reader waits", async () => {
    const mailbox = new OutboundMailbox<string>();
    const lease = mailbox.tryAcquire();
    if (!lease) {
      throw new Error("Expected outbound mailbox lease");
    }
    const reader = createSseBody(lease).getReader();
    const read = reader.read();
    await flushMicrotasks();

    mailbox.abort();

    await expect(read).resolves.toEqual({ done: true, value: undefined });
  });

  it("sends keep-alives only while its reader waits, and aborts once stopped otherwise", async () => {
    vi.useFakeTimers();

    try {
      const mailbox = new OutboundMailbox<string>();
      const lease = mailbox.tryAcquire();
      if (!lease) {
        throw new Error("Expected outbound mailbox lease");
      }
      const reader = createSseBody(lease).getReader();

      // The reader takes a keep-alive, then stops asking, as if stuck writing
      // it to a client that stopped reading.
      const read = reader.read();
      await vi.advanceTimersByTimeAsync(15_000);
      const { value } = await read;
      expect(value && decodeText(value)).toBe(serializeSseKeepAlive());
      await vi.advanceTimersByTimeAsync(60_000);

      // Even a clean shutdown aborts the body, and no keep-alives piled up.
      mailbox.abort();
      await expect(reader.read()).rejects.toThrow("ACP connection is closed");
    } finally {
      vi.useRealTimers();
    }
  });
});

async function flushMicrotasks(): Promise<void> {
  await Promise.resolve();
  await Promise.resolve();
}

function decodeText(chunk: Uint8Array): string {
  return new TextDecoder().decode(chunk);
}

import { describe, expect, expectTypeOf, it } from "vitest";
import { agent as createV1AgentApp, methods as v1Methods } from "./acp.js";
import { AgentProtocolRouter } from "./protocol-router.js";
import {
  PROTOCOL_VERSION as V2_PROTOCOL_VERSION,
  agent as createV2AgentApp,
  methods as v2Methods,
} from "./v2/acp.js";

import type { AgentApp as V1AgentApp } from "./acp.js";
import type {
  AgentConnectOptions,
  AgentConnectionLifecycle,
  AgentConnector,
} from "./connection.js";
import type { AnyRequest, AnyResponse } from "./jsonrpc.js";
import type { WireStream as Stream } from "./stream.js";
import type { AgentApp as V2AgentApp } from "./v2/acp.js";

type WireMessage =
  Stream["readable"] extends ReadableStream<infer Message> ? Message : never;

describe("AgentProtocolRouter", () => {
  it("accepts both AgentApp generations as connectors", () => {
