    const connection = registry.createConnection(
      {
        connect(stream) {
          agentStream = stream;
        },
      },
      "websocket",
    );
    try {
      const lease = connection.allOutbound.tryAcquire();
      if (!lease) {
        throw new Error("Expected outbound mailbox lease");
      }

      connection.startRouter();

      if (!agentStream) {
        throw new Error("Expected agent stream");
